const out = $json.output || '';
const w = $('Webhook: consulta nueva').item.json.body;
const alta = /d[eé]bit|descont|reclam|estaf|denunci|defensa del consumidor|enojad|harto|inaceptable/i.test(w.mensaje || '');
const derivar = /analista de la butaca/i.test(out) || alta;
return { json: { numero: w.numero, respuesta: out, derivar, prioridad: alta ? 'ALTA' : 'NORMAL' } };
